fn all_odd_at_odd_positions(arr: &Vec<usize>) -> bool {
    // Requires that the input array is non-null
    // Ensures that the return value is true if all odd values are at odd positions
    // and false otherwise
    // Invariant: For all indices i in the range of arr, if i is even, arr[i] must be even
    // and if i is odd, arr[i] must be odd.
    // Decreases the length of the array with each iteration
    let n = arr.len();
    let mut i = 0;
    while i < n {
        // Check the invariant
        assert!(i < n);
        if i % 2 == 0 && arr[i] % 2 != 0 {
            return false; // Even index but odd value
        }
        if i % 2 == 1 && arr[i] % 2 != 1 {
            return false; // Odd index but even value
        }
        i += 1;
    }
    true // All checks passed
}

